import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DPaNRfRs.js";var i=JSON.parse(`{"title":"Queues","description":"","frontmatter":{},"headers":[],"relativePath":"guide/queues/index.md","filePath":"guide/queues/README.md","lastUpdated":1785480634000}`),a={name:`guide/queues/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to “Queues”">​</a></h1><p>A Queue is nothing more than a list of jobs waiting to be processed. The jobs can be small, message like, so that the queue can be used as a message broker, or they can be larger long running jobs.</p><p>Queues are controlled with the <code>Queue</code> class. As all classes in BullMQ, this is a lightweight class with a handful of methods that gives you control over the queue:</p><div class="language-typescript"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> queue</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Queue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Cars&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>See <a href="./../connections">Connections</a> for details on how to pass Redis details to use by the queue.</p></div><p>When you instantiate a Queue, BullMQ will just <em>upsert</em> a small &quot;meta-key&quot;, so if the queue existed before it will just pick it up and you can continue adding jobs to it.</p><p>The most important method is probably the <a href="https://docs.bullmq.io/api/classes/v6.Queue.html#add" target="_blank" rel="noreferrer"><em><strong>add</strong></em></a> method. This method allows you to add jobs to the queue in different fashions:</p><div class="language-typescript"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> queue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;paint&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { color: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;red&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>The code above will add a job named <em>paint</em> to the queue, with payload <code>{ color: &#39;red&#39; }</code>. This job will now be stored in Redis in a list waiting for some worker to pick it up and process it. Workers may not be running when you add the job, however as soon as one worker is connected to the queue it will pick the job and process it.</p><p>When adding a job you can also specify an options object. This options object can dramatically change the behaviour of the added jobs. For example you can add a job that is delayed:</p><div class="language-typescript"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> queue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;paint&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { color: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;blue&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, { delay: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>The job will now wait <strong>at</strong> <strong>least</strong> 5 seconds before it is processed.</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>Prior to BullMQ 2.0, in order for delay jobs to work you need to have at least one <code>QueueScheduler</code> somewhere in your infrastructure. Read more <a href="./../queuescheduler">here</a>.</p><p>From BullMQ 2.0 and onwards, the <code>QueueScheduler</code> is not needed anymore.</p></div><p>There are many other options available such as priorities, backoff settings, lifo behaviour, remove-on-complete policies, etc. Please check the remainder of this guide for more information regarding these options.</p><h2 id="read-more" tabindex="-1">Read more: <a class="header-anchor" href="#read-more" aria-label="Permalink to “Read more:”">​</a></h2><ul><li>💡 <a href="https://docs.bullmq.io/api/classes/v6.Queue.html" target="_blank" rel="noreferrer">Queue API Reference</a></li></ul>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};